// ======================================================
// SENSOR KEY
// ======================================================
let sensorKey = `${msg.plc_code}/${msg.sensor_code}`;
let now = Date.now();

// ======================================================
// AMBIL INTERVAL
// ======================================================
let intervalMap = flow.get("intervalMap") || {};
let lastInsertMap = flow.get("lastInsertMap") || {};

// fallback default 30 menit
let intervalMin = intervalMap[sensorKey] || 30;
let intervalMs = intervalMin * 60 * 1000;
let intervalSec = intervalMin * 60;
let lastInsert = lastInsertMap[sensorKey] || 0;

// ======================================================
// CEK INTERVAL
// ======================================================
if ((now - lastInsert) < intervalMs) {
    return null;
}

// ======================================================
// UPDATE LAST INSERT
// ======================================================
lastInsertMap[sensorKey] = now;
flow.set("lastInsertMap", lastInsertMap);

// ======================================================
// BUILD SQL HISTORY
// ======================================================
msg.topic = `
INSERT INTO sensor_history
(
    plc_code,
    sensor_code,
    value,
    timestamp
)
SELECT
    plc_code,
    sensor_code,
    AVG(value) AS value,
    FROM_UNIXTIME(
        CEILING(
            UNIX_TIMESTAMP(timestamp) / ${intervalSec}
        ) * ${intervalSec}
    ) AS time_bucket
FROM sensor_realtime
WHERE sensor_code = '${msg.sensor_code}'
AND plc_code = '${msg.plc_code}'
AND timestamp >= DATE_SUB(NOW(), INTERVAL 7 DAY)
GROUP BY
    plc_code,
    sensor_code,
    time_bucket
ON DUPLICATE KEY UPDATE
    value = VALUES(value);
`;

return msg;

let lastSeenSensor = flow.get("lastSeenSensor") || {};
let statusSensor = flow.get("statusSensor") || {};

let timeoutMs = 65000; // interval PLC = 1 menit → timeout 65 detik
let now = Date.now();

let queries = [];

for (let key in lastSeenSensor) {
    let last = lastSeenSensor[key];

    if (now - last > timeoutMs) {

        if (statusSensor[key] !== "offline") {
            statusSensor[key] = "offline";
            flow.set("statusSensor", statusSensor);

            let [plc_code, sensor_code] = key.split("/");

            queries.push(`
                INSERT INTO sensor_log 
                (plc_code, sensor_code, status, event_time)
                VALUES ('${plc_code}', '${sensor_code}', '0', NOW());
            `);
        }
    }
}

if (queries.length > 0) {
    return { topic: queries.join("\n") };
}

return null;

// Contoh: msg.topic = "data/07/RT0201/7020449001020126076"
// Ambil sensor code dari topik MQTT
const topicParts = msg.topic.split("/");
const sensorCode = topicParts[2]; // "RT0201"

// Ambil data dari payload
const data = msg.payload;

// Pastikan payload valid
if (!data || !sensorCode) return null;

// Buat pesan bersih untuk WebSocket
msg.payload = {
  sensor_code: sensorCode,
  value: Number(data.value),
  timestamp: data._terminalTime
};

return msg;

// function node — output ke MySQL (pastikan function node memiliki 3 output seperti sebelumnya)
if (typeof msg.payload === "string") {
    try { msg.payload = JSON.parse(msg.payload); } 
    catch (e) {
        node.error("Invalid JSON", msg);
        msg.statusCode = 400; msg.payload = { error: "Invalid JSON" };
        return [null, msg, null];
    }
}

const data = msg.payload;
if (!data.sensor_code || data.value === undefined) {
    msg.statusCode = 400; msg.payload = { error: "sensor_code dan value wajib diisi" };
    return [null, msg, null];
}

// Ambil timestamp; jika tidak ada gunakan now
let ts = data.timestamp || new Date().toISOString();
// ubah ISO -> "YYYY-MM-DD HH:MM:SS"
ts = ts.replace('T', ' ').replace('Z', '').split('.')[0]; // menghapus ms

// buat query (nilai numeric tanpa quotes)
msg.topic = `
  INSERT INTO sensor_history (sensor_code, value)
  VALUES ('${data.sensor_code}', ${Number(data.value)})
`;

node.warn("Query: " + msg.topic);
return [msg, null, msg];

msg.payload = { success: true, message: "Data berhasil disimpan" };
msg.statusCode = 200;
return msg;

let rows = msg.payload;

// Pastikan hasil dari MySQL berupa array
if (!Array.isArray(rows)) {
    node.warn("Payload bukan array, isi payload: " + JSON.stringify(rows));
    msg.payload = {
        status: "error",
        message: "Data dari database tidak berupa array",
        raw_payload: rows
    };
    return msg;
}

// Format response API
msg.payload = {
    status: "success",
    timestamp_api: new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" }),
    sensors: rows.map(r => {
        let timestamp = new Date(r.timestamp);
        return {
            plc_code: r.plc_code, // kalau kolom ini ada di tabel
            sensor_code: r.sensor_code,
            value: r.value,
            timestamp: timestamp.toLocaleString("id-ID", { timeZone: "Asia/Jakarta" })
        };
    })
};

return msg;

// Ambil sensor dari URL parameter
const sensorCode = msg.req.params.sensor;

let sql = `
SELECT sr.plc_code, sr.sensor_code, sr.value, sr.timestamp
FROM sensor_realtime sr
INNER JOIN (
    SELECT sensor_code, MAX(timestamp) AS latest_timestamp
    FROM sensor_realtime
    GROUP BY sensor_code
) t
ON sr.sensor_code = t.sensor_code
AND sr.timestamp = t.latest_timestamp
`;

if (sensorCode) {
    sql += ` WHERE sr.sensor_code = '${sensorCode}'`;
}

sql += " ORDER BY sr.sensor_code;";

msg.topic = sql;
return msg;

let plant_code = msg.plant_code;
let sensor_code = msg.sensor_code;

msg.topic = `iot/${plant_code}/${sensor_code}`;

msg.payload = {
    sensor_code: msg.sensor_code,
    value: msg.value,
    cycleValue: msg.cycleValue,
    timestamp: msg.timestamp
};

return msg;

// ======================================================
// VALIDATE TOPIC
// ======================================================
if (typeof msg.topic !== "string") {
    return null;
}

// ======================================================
// PARSE TOPIC
// ======================================================
let parts = msg.topic.split("/");
if (parts.length < 4) {
    return null;
}
let plant_code = parts[1];
let plc_code = parts[3];

// ======================================================
// VALIDATE PAYLOAD
// ======================================================
let payload = msg.payload || {};
let sensor_code = (payload._groupName.substring(0, 6) || "").toString().trim();
let timestamp = payload._terminalTime;
let rawValue = payload.data;
let interval = payload.interval;
let cycleValue = payload.data_cycle ?? null;

if (
    !plant_code ||
    !sensor_code ||
    !plc_code ||
    !timestamp
) {
    return null;
}

// ======================================================
// VALUE CONVERSION
// ======================================================
let measurement_code = sensor_code.substring(2, 4);
let valueConverted;
switch (measurement_code) {
    case "01":
        valueConverted = parseFloat(rawValue) / 1000;
        break;
    case "02":
    case "03":
    case "04":
        valueConverted = parseFloat(rawValue) / 10;
        break;
    default:
        valueConverted = parseFloat(rawValue);
}

// ======================================================
// NORMALIZE MESSAGE
// ======================================================
msg.plant_code = plant_code;
msg.sensor_code = sensor_code;
msg.plc_code = plc_code;
msg.value = valueConverted;
msg.cycleValue = cycleValue;
msg.interval = interval;
msg.timestamp = timestamp;

return msg;

let lastSeenSensor = flow.get("lastSeenSensor") || {};
let statusSensor = flow.get("statusSensor") || {};
let sensorKey = `${msg.plc_code}/${msg.sensor_code}`;
let now = Date.now();

// ============================================
// UPDATE LAST SEEN
// ============================================
lastSeenSensor[sensorKey] = now;
flow.set("lastSeenSensor", lastSeenSensor);

// ============================================
// FIRST ONLINE DETECT
// ============================================
if (statusSensor[sensorKey] !== "online") {
    statusSensor[sensorKey] = "online";
    flow.set("statusSensor", statusSensor);
    return [msg, null];
} 
return [null, msg];

msg.topic = `
INSERT INTO sensor_log
(
    plc_code,
    sensor_code,
    status,
    timestamp
)
VALUES (
    '${msg.plc_code}',
    '${msg.sensor_code}',
    '1',
    '${msg.timestamp}'
);
`;

return msg;

// 1. Ambil metadata dari memori Global
let metadata = flow.get("sensor_metadata");

// Cegah error jika metadata atau objek sensors belum terdefinisi
if (!metadata || !metadata.sensors || Object.keys(metadata.sensors).length === 0) {
    node.error("sensor_metadata atau list sensors belum disetting di Global Context", msg);
    return null;
}

// Ambil kunci sensor dari properti .sensors
const codes = Object.keys(metadata.sensors);
const sqlCodes = codes.map(c => `'${c}'`).join(',');

msg.isTimerReport = true;

// 2. Bangun Query dinamis berdasarkan sensor yang aktif
msg.topic = `
    SELECT t1.* FROM sensor_realtime t1
    INNER JOIN (
        SELECT sensor_code, MAX(id) as mid
        FROM sensor_realtime
        WHERE sensor_code IN (${sqlCodes})
        GROUP BY sensor_code
    ) t2 ON t1.id = t2.mid
    ORDER BY t1.sensor_code ASC;
`;

return msg;

if (msg.isTimerReport !== true || !Array.isArray(msg.payload)) {
    return null;
}

// 1. Ambil Metadata dari Global
let metadata = flow.get("sensor_metadata");
if (!metadata || !metadata.sensors || Object.keys(metadata.sensors).length === 0) {
    node.error("Metadata atau list sensors kosong saat merender laporan", msg);
    return null;
}

const rows = msg.payload;
const waktuWIB = new Date().toLocaleString('id-ID', {
    timeZone: 'Asia/Jakarta',
    hour: '2-digit', minute: '2-digit', hour12: false
});

// 2. Ambil nama Plant langsung dari properti tingkat atas
const namaPlant = metadata.plant || "UNDEFINED";

// 3. Susun Header Laporan secara Dinamis
let report = `📊 *REKAPITULASI SUHU: PLANT ${namaPlant.toUpperCase()}* 📊\n`;
report += "--------------------------\n\n";

// 4. Loop Data berdasarkan konfigurasi metadata.sensors
Object.keys(metadata.sensors).forEach((code) => {
    const info = metadata.sensors[code];
    const rowData = rows.find(r => r.sensor_code === code);
    let teksSuhu = "_Tidak ada data_";

    if (rowData) {
        const nilaiSuhu = parseFloat(rowData.value || 0);

        if (nilaiSuhu < 850) {
            teksSuhu = `*${nilaiSuhu.toFixed(1).replace('.', ',')} °C*`;
        } else {
            teksSuhu = "_Sensor Off (850)_";
        }
    }

    // Format pengiriman pesan ke WA
    report += `*${info.name} (${code})*\n`;
    report += `Suhu : ${teksSuhu}\n\n`;
});

report += "--------------------------\n";
report += `⏰ _Update Otomatis: ${waktuWIB} WIB_`;

// 5. Masukkan teks laporan ke payload utama
msg.payload = report;

node.status({ fill: "green", shape: "dot", text: "Template Siap: " + waktuWIB });

return msg;

msg.topic = `
CREATE TABLE IF NOT EXISTS sensor_log (
    id INT NOT NULL AUTO_INCREMENT,
    plc_code VARCHAR(50),
    sensor_code VARCHAR(50),
    status VARCHAR(20),
    event_time TIMESTAMP NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);
`;

return msg;

msg.topic = `

CREATE TABLE IF NOT EXISTS sensor_realtime (
    id INT NOT NULL AUTO_INCREMENT,
    plc_code CHAR(19),
    sensor_code CHAR(6) NOT NULL,
    value DECIMAL(8,2) NOT NULL,
    data_cycle DECIMAL(8,0) DEFAULT NULL,
    timestamp TIMESTAMP NOT NULL,
    insert_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

`;

return msg;
